{"function": "() => {
  // Try to get abstract text by looking for the region with aria-label "Abstract"
  const abstractRegion = document.querySelector('section[aria-label="Abstract"], [aria-label="Abstract"]');
  if (abstractRegion) {
    // Get all text content
    const text = abstractRegion.textContent || abstractRegion.innerText;
    return text.trim();
  }

  // Alternative: look for heading "Abstract" and get following paragraph
  const abstractHeading = Array.from(document.querySelectorAll('h2, h3')).find(h => 
    h.textContent && h.textContent.includes('Abstract')
  );
  if (abstractHeading) {
    let nextElement = abstractHeading.nextElementSibling;
    while (nextElement) {
      if (nextElement.tagName === 'P') {
        return nextElement.textContent || nextElement.innerText;
      }
      nextElement = nextElement.nextElementSibling;
    }
  }

  return 'Abstract not found';
}"}

