{"function": "() => {
    // Find the abstract region
    const abstractRegion = document.querySelector('section[aria-label="Abstract"], [role="region"][aria-label="Abstract"], .Abstract');
    if (abstractRegion) {
        // Get the text content, excluding the "Abstract" heading
        const abstractText = abstractRegion.textContent.replace(/^Abstract/i, '').trim();
        return abstractText;
    }
    // Fallback: look for h2 with text Abstract and get following paragraph
    const abstractHeading = Array.from(document.querySelectorAll('h2')).find(h2 => h2.textContent.trim() === 'Abstract');
    if (abstractHeading) {
        const nextPara = abstractHeading.nextElementSibling;
        if (nextPara && nextPara.tagName === 'P') {
            return nextPara.textContent.trim();
        }
    }
    return null;
}"}

